    if (q('[data-cmtimer]')) { CM.timer = { 0: 3, 3: 10, 10: 0 }[CM.timer]; cmRender(); return true; }
    if (q('[data-cmgrid]')) { CM.grid = !CM.grid; cmRender(); return true; }
