        if (o?.k === 'op' && (o.v === '×' || o.v === '÷' || o.v === 'mod')) { next(); const b = unaryP().v; if (o.v === '×') a = { v: a.v * b }; else if (o.v === 'mod') a = { v: ((a.v % b) + b) % b }; else { if (b === 0) throw 'Can’t divide by 0'; a = { v: a.v / b }; } }
