      const L = caLast(); if (L?.k === 'num') { if (k === '.' && L.v.includes('.')) return; if (L.v.replace(/[-.]/g, '').length >= 15) return; L.v = L.v === '0' && k !== '.' ? k : L.v === '-0' && k !== '.' ? '-' + k : L.v + k; }
