    if (q('#ca-expr') && CA.fresh) { navigator.clipboard?.writeText(String(+CA.t[0].v)).catch(() => {}); const p = $('#ca-prev'); p.textContent = 'Copied'; setTimeout(() => { if (p.textContent === 'Copied') p.textContent = ''; }, 1200); return true; }
