  const cvBounds = S => { const x = Math.min(...S.map(n => n.x)), y = Math.min(...S.map(n => n.y)), X = Math.max(...S.map(n => n.x + n.w)), Y = Math.max(...S.map(n => n.y + n.h)); return { x, y, w: X - x, h: Y - y }; };
