      keep.add(sp.key); el.classList.toggle('over', sp.over); el.style.opacity = sp.op; el.style.mixBlendMode = sp.blend; el.style.transform = sp.wrapT; el.style.transformOrigin = sp.origin; el.style.zIndex = n;
