    const card = $(`#pg-body [data-pgi="${id}"]`), shot = card?.querySelector('.pgshot'), el = shot?.querySelector(`[data-kp="${ev}"]`); if (!el) { lToast(pgW(), 'This check is proved by a test, not a picture'); return; }
